def parts(n):
 return [t for t in re.findall('[a-z]+',unicodedata.normalize('NFKD',n).encode('ascii','ignore').decode().lower()) if t not in ['jr','sr','ii','iii','iv']]
def compatible(n,s):
 a,b=parts(n),parts(s)
 if not a or not b or a[-1]!=b[-1] or a[0]!=b[0]:return False
 return len(a)!=len(b) or all(x==y or len(x)==1 and y.startswith(x) or len(y)==1 and x.startswith(y) for x,y in zip(a,b))
